bool isPrime(int n)
{
    if (n < 2)
    {
        return false;
    }
    for (int d{ 2 }; d * d <= n; ++d)
    {
        if (n % d == 0)
        {
            return false;
        }
    }
    return true;
}

unitTests:
TEST("small primes") { CHECK(isPrime(2)); CHECK(isPrime(3)); CHECK(isPrime(5)); CHECK(isPrime(13)); }
TEST("small non-primes") { CHECK(!isPrime(4)); CHECK(!isPrime(9)); CHECK(!isPrime(15)); CHECK(!isPrime(25)); }
TEST("0, 1 and negatives are not prime") { CHECK(!isPrime(0)); CHECK(!isPrime(1)); CHECK(!isPrime(-7)); }
TEST("bigger numbers") { CHECK(isPrime(7919)); CHECK(!isPrime(7917)); CHECK(isPrime(104729)); }

